select chk, val, ok from (
  select 1 o, 'schema: 005 yangi jadvallar (25)' chk, (select count(*) from pg_tables where schemaname = 'public' and tablename in ('course_modules','lessons','course_assignments','lesson_progress','learning_paths','learning_path_courses','course_instructors','org_invitations','content_policies','medical_topics','evidence_grading_schemes','evidence_sources','evidence_source_topics','question_evidence','question_versions','question_publications','question_review_assignments','question_reviews','question_quality_scores','research_queries','research_results','ai_jobs','evidence_summaries','evidence_monitors','evidence_events'))::text val,
     (select count(*) from pg_tables where schemaname = 'public' and tablename in ('course_modules','lessons','course_assignments','lesson_progress','learning_paths','learning_path_courses','course_instructors','org_invitations','content_policies','medical_topics','evidence_grading_schemes','evidence_sources','evidence_source_topics','question_evidence','question_versions','question_publications','question_review_assignments','question_reviews','question_quality_scores','research_queries','research_results','ai_jobs','evidence_summaries','evidence_monitors','evidence_events')) = 25 ok
  union all select 2, 'RLS: o''chiq public jadvallar', coalesce((select string_agg(tablename, ',') from pg_tables where schemaname = 'public' and not rowsecurity), '0'), not exists (select 1 from pg_tables where schemaname = 'public' and not rowsecurity)
  union all select 3, 'FK: CASCADE (public sxemadagi 005 jadvallari)', (select count(*) from pg_constraint c where c.contype = 'f' and c.confdeltype = 'c' and c.connamespace = 'public'::regnamespace and c.conrelid::regclass::text not in (select tablename from backup.tables_pre005_20261123))::text,
     (select count(*) from pg_constraint c where c.contype = 'f' and c.confdeltype = 'c' and c.connamespace = 'public'::regnamespace and c.conrelid::regclass::text not in (select tablename from backup.tables_pre005_20261123)) = 0
  union all select 4, 'FK: questions.module_id → course_modules (validated)', (select case when convalidated then 'validated' else 'NOT' end from pg_constraint where conname = 'questions_module_fk'), (select convalidated from pg_constraint where conname = 'questions_module_fk')
  union all select 5, 'indexes: yangi', ((select count(*) from pg_indexes where schemaname = 'public') - (select count(*) from backup.indexes_pre005_20261123))::text, (select count(*) from pg_indexes where schemaname = 'public') > (select count(*) from backup.indexes_pre005_20261123)
  union all select 6, 'permissions (29 + 16)', (select count(*) from public.permissions)::text, (select count(*) from public.permissions) = 45
  union all select 7, 'role_permissions (Impuls)', (select count(*) from public.role_permissions)::text, (select count(*) from public.role_permissions) > 56
  union all select 8, 'anon: 005 jadvallarida grant yo''q', (select count(*) from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and table_name in ('evidence_sources','question_evidence','question_reviews','question_versions','course_assignments','lesson_progress','research_results','ai_jobs'))::text,
     (select count(*) from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and table_name in ('evidence_sources','question_evidence','question_reviews','question_versions','course_assignments','lesson_progress','research_results','ai_jobs')) = 0
  union all select 9, 'org isolation: org_id NULL (tashkilot jadvallari)', ((select count(*) from public.course_modules where org_id is null) + (select count(*) from public.lessons where org_id is null) + (select count(*) from public.learning_paths where org_id is null) + (select count(*) from public.question_versions where org_id is null))::text,
     ((select count(*) from public.course_modules where org_id is null) + (select count(*) from public.lessons where org_id is null) + (select count(*) from public.learning_paths where org_id is null) + (select count(*) from public.question_versions where org_id is null)) = 0
  union all select 10, 'evidence tables: manbalar / bog''lanishlar / review (soxta ma''lumot yo''q)', (select count(*) from public.evidence_sources) || ' / ' || (select count(*) from public.question_evidence) || ' / ' || (select count(*) from public.question_reviews),
     (select count(*) from public.evidence_sources) = 0 and (select count(*) from public.question_evidence) = 0 and (select count(*) from public.question_reviews) = 0
  union all select 11, 'evidence: grading schemes (metadata)', (select count(*) from public.evidence_grading_schemes)::text, (select count(*) from public.evidence_grading_schemes) = 5
  union all select 12, 'question versions: v1 = 131, snapshot matni backup bilan bir xil', (select count(*) from public.question_versions v join backup.questions_pre005_20261123 b on b.id = v.question_id where v.version_no = 1 and v.snapshot ->> 'stem' = b.stem and v.snapshot -> 'answer' = b.answer)::text,
     (select count(*) from public.question_versions v join backup.questions_pre005_20261123 b on b.id = v.question_id where v.version_no = 1 and v.snapshot ->> 'stem' = b.stem and v.snapshot -> 'answer' = b.answer) = 131
  union all select 13, 'question publications (v1)', (select count(*) from public.question_publications)::text, (select count(*) from public.question_publications) = 131
  union all select 14, 'exam eligibility: yaroqli savollar (unknown evidence → 0)', (select count(*) from public.questions q where public._q_exam_eligible(q))::text, (select count(*) from public.questions q where public._q_exam_eligible(q)) = 0
  union all select 15, 'exam eligibility: review_required (evidence_unknown_policy)', (select count(*) from public.questions where workflow_status = 'review_required' and evidence_status = 'unknown' and review_reason = 'evidence_unknown_policy_2026_11')::text,
     (select count(*) from public.questions where workflow_status = 'review_required' and evidence_status = 'unknown' and review_reason = 'evidence_unknown_policy_2026_11') = 131
  union all select 16, 'data: profiles', (select count(*) from public.profiles)::text, (select count(*) from public.profiles) = 1
  union all select 17, 'data: courses', (select count(*) from public.courses)::text, (select count(*) from public.courses) = 13
  union all select 18, 'data: questions (o''chirilmagan, stem/answer o''zgarmagan)', (select count(*) from public.questions q join backup.questions_pre005_20261123 b on b.id = q.id where q.stem = b.stem and q.answer = b.answer)::text,
     (select count(*) from public.questions) = 131 and (select count(*) from public.questions q join backup.questions_pre005_20261123 b on b.id = q.id where q.stem = b.stem and q.answer = b.answer) = 131
  union all select 19, 'data: exam_configs', (select count(*) from public.exam_configs)::text, (select count(*) from public.exam_configs) = 13
  union all select 20, 'historical: exam_attempts aynan backup bilan', (select count(*) from public.exam_attempts a join backup.exam_attempts_pre005_20261123 b on b.id = a.id where (to_jsonb(a) - 'question_versions') = to_jsonb(b))::text || '/' || (select count(*) from backup.exam_attempts_pre005_20261123),
     (select count(*) from public.exam_attempts a join backup.exam_attempts_pre005_20261123 b on b.id = a.id where (to_jsonb(a) - 'question_versions') = to_jsonb(b)) = (select count(*) from backup.exam_attempts_pre005_20261123)
     and (select count(*) from public.exam_attempts) = (select count(*) from backup.exam_attempts_pre005_20261123)
  union all select 21, 'data: certificates', (select count(*) from public.certificates)::text, (select count(*) from public.certificates) = 0
  union all select 22, 'data: docs (backup bilan teng)', (select count(*) from public.docs)::text, (select count(*) from public.docs) = (select count(*) from backup.docs_pre005_20261123)
  union all select 23, 'data: employees / departments / organizations', (select count(*) from public.employees) || ' / ' || (select count(*) from public.departments) || ' / ' || (select count(*) from public.organizations),
     (select count(*) from public.employees) = (select count(*) from backup.employees_pre005_20261123) and (select count(*) from public.departments) = 10 and (select count(*) from public.organizations) = 1
  union all select 24, 'Abdulaziz', (select role || ' / ' || status || ' / ' || department from public.profiles where id = '262a128c-6fb7-470e-9452-5468cd6797c0'),
     (select role || ' / ' || status || ' / ' || department from public.profiles where id = '262a128c-6fb7-470e-9452-5468cd6797c0') = 'super_admin / active / Kardiologiya'
  union all select 25, 'structure seed: modul / dars / path / bog''lanish', (select count(*) from public.course_modules) || ' / ' || (select count(*) from public.lessons) || ' / ' || (select count(*) from public.learning_paths) || ' / ' || (select count(*) from public.learning_path_courses),
     (select count(*) from public.course_modules) = 34 and (select count(*) from public.lessons) = 47 and (select count(*) from public.learning_paths) = 9 and (select count(*) from public.learning_path_courses) = 63
  union all select 26, 'test ma''lumoti yo''q: assignments / progress / invitations / ai_jobs / research', ((select count(*) from public.course_assignments) + (select count(*) from public.lesson_progress) + (select count(*) from public.org_invitations) + (select count(*) from public.ai_jobs) + (select count(*) from public.research_queries))::text,
     ((select count(*) from public.course_assignments) + (select count(*) from public.lesson_progress) + (select count(*) from public.org_invitations) + (select count(*) from public.ai_jobs) + (select count(*) from public.research_queries)) = 0
  union all select 27, 'auth.users o''zgarmagan', (select count(*) from auth.users)::text, (select count(*) from auth.users) = 1
  union all select 28, 'schema_migrations', (select string_agg(version, ',' order by version) from public.schema_migrations), (select count(*) from public.schema_migrations where version in ('005a','005b','005c')) = 3
) x order by o;
